        /// <summary>
        /// 标准化字符串：移除空格并转换为小写
        /// </summary>
        /// <param name="input">输入字符串</param>
        /// <returns>标准化后的字符串</returns>
        public static string NormalizeString(string input)
        {
            return input?.Replace(" ", "").Replace("-", "").ToLowerInvariant() ?? string.Empty;
        }

        public static async ValueTask<PokeType?> GetTypeAsync(int id)
        {
            if (_pokeTypes.TryGetValue(id, out var type))
            {
                return type;
            }
            else
            {
                var nType = PokemonDBInMemory.Types.Find(s => s.Id == id);
                if (nType != null)
                {
                    _pokeTypes.TryAdd(id, nType);
                    _pokeTypeNameId.TryAdd(nType.Name_Chs, id);
                    _pokeTypeNameId.TryAdd(nType.Name_Eng, id);
                    _pokeTypeNameId.TryAdd(nType.Name_Jpn, id);
                    return nType;
                }
                else
                {
                    return null;
                }
            }
        }
        public static async ValueTask<PokeType?> GetTypeAsync(string name)
        {
            var normalizedName = NormalizeString(name);
            if (_pokeTypeNameId.TryGetValue(normalizedName, out var type))
            {
                return await GetTypeAsync(type);
            }
            else
            {
                {
                    var nType = PokemonDBInMemory.Types.FirstOrDefault
                        (n => NormalizeString(n.Name_Chs) == normalizedName || 
                              NormalizeString(n.Name_Eng) == normalizedName || 
                              NormalizeString(n.Name_Jpn) == normalizedName);
                    if (nType != null)
                    {
                        _pokeTypes.TryAdd(nType.Id, nType);
                        _pokeTypeNameId.TryAdd(NormalizeString(nType.Name_Chs), nType.Id);
                        _pokeTypeNameId.TryAdd(NormalizeString(nType.Name_Eng), nType.Id);
                        _pokeTypeNameId.TryAdd(NormalizeString(nType.Name_Jpn), nType.Id);
                        return nType;
                    }
                    else
                    {
                        return null;
                    }
                }
            }
        }
