        public static async ValueTask<Pokemon?> GetPokemonFromPsNameAsync(string name)
        {
            var normalizedName = NormalizeString(name);
            if (_psPokemonId.TryGetValue(normalizedName, out var id))
            {
                return await GetPokemonAsync(id);
            }
            else
            {
                {

                    var nPSPoke = PokemonDBInMemory.PSPokemons.FirstOrDefault(p => NormalizeString(p.PSName) == normalizedName);
                    if (nPSPoke != null)
                    {
                        // Todo: 为啥要try
                        _psPokemonId.TryAdd(normalizedName, nPSPoke.PokemonId ?? 0);
                        return GetPokemonAsync(nPSPoke.PokemonId ?? 0).Result;
                    }
                    else
                    {
                        return null;
                    }
                }
            }
        }

